import axios_api from "./axios";
import { apiPath } from "./config";

// 드롭다운 아이템 목록
export const getItems = async () => {
  const url = apiPath("/plan/itemlist/main");   // 데모=FRONT_BASE+상대경로
  const { data } = await axios_api.get(url);
  return data; // [{ itemNo, itemName }]
};

// 예측 시계열
export const getForecastSeries = async (itemNo, h = 12) => {
  const url = apiPath("/forecast/series");
  const { data } = await axios_api.get(url, { params: { itemNo, h } });
  return data;
};
